# sound effects for ep28 — cues(B, bs, be, mk, cue, end_start); times on the story timeline (cover offset added for you)
def cues(B, bs, be, mk, cue, end_start):
    a = bs(0); cue(a + .05, 'whoosh'); cue(mk(0, 'cig', .05) + .3, 'slide_up', .35); cue(mk(0, 'yellow', .2) + .3, 'sad', .3); cue(mk(0, 'ask', .85), 'boing', .35)
    a = bs(1); cue(a, 'whoosh'); cue(mk(1, 'nic', .15), 'pop', .35); s = mk(1, 'shrink', .3); cue(s + .1, 'slide_down', .4); cue(s + .3, 'thud', .35); cue(mk(1, 'less', .75), 'sad', .3)
    a = bs(2); cue(a, 'whoosh'); cue(mk(2, 'plaque', .1) + .1, 'slide_up', .3); cue(mk(2, 'calc', .3) + .5, 'thud', .4)
    g = mk(2, 'germ', .55)
    for k in range(5): cue(g + k * .18, 'pop', .25)
    cue(mk(2, 'term', .8), 'boing', .35)
    a = bs(3); cue(a, 'whoosh'); cue(mk(3, 'bleed', .25) + .2, 'tick', .35); cue(mk(3, 'color', .5) + .1, 'tick', .35); cue(mk(3, 'hidden', .75) + .2, 'sad', .4)
    a = bs(4); cue(a, 'whoosh'); cue(mk(4, 'bone', .2), 'slide_down', .4); t = mk(4, 'term', .6); cue(t - .2, 'boing', .45); cue(t + .4, 'ding', .35); cue(mk(4, 'two', .9), 'thud', .5)
    a = bs(5); cue(a, 'whoosh'); sc = mk(5, 'scale', .2); cue(sc, 'drill', .25); cue(sc + .3, 'thud', .5)
    for k in range(4): cue(sc + .4 + k * .15, 'pop', .3)
    cue(mk(5, 'plane', .4), 'drill', .22); cue(mk(5, 'under', .7) + .8, 'sparkle', .35)
    a = bs(6); cue(a, 'whoosh'); cue(a + .2, 'slide_up', .3); cue(mk(6, 'slow', .3) + .2, 'sad', .35); cue(mk(6, 'less', .6) + .1, 'tick', .35)
    a = bs(7); cue(a, 'whoosh'); q = mk(7, 'quit', .05) + .35; cue(q, 'thud', .55); cue(q + .1, 'boing', .35); cue(mk(7, 'heal', .2) + .8, 'chime', .4); cue(mk(7, 'num', .75) - .3, 'ding', .45)
    a = bs(8); cue(a, 'whoosh'); cue(mk(8, 'no', .6), 'boing', .5); cue(mk(8, 'hide', .75) + .1, 'ding', .35)
    cue(bs(9), 'fanfare'); cue(end_start + .15, 'sparkle')
